PREFIXES = ["auto", "bio", "cloud", "code", "data", "cyber", "debug", "digital",
            "electro", "hyper", "micro", "multi", "nano", "neuro", "open", "over",
            "proto", "quantum", "smart", "soft", "sub", "super", "tele", "trans",
            "ultra", "web", "wireless"]
SUFFIXES = ["able", "access", "action", "active", "agent", "analysis", "api",
            "app", "array", "auth", "aware", "based", "binary", "bit", "block",
            "bot", "branch", "build", "cache", "call", "chain", "change", "chat",
            "class", "client", "cloud", "cluster", "code", "compiler", "compute",
            "config", "connect", "context", "control", "core", "data", "debug",
            "decode", "design", "device", "digital", "disk", "drive", "engine",
            "event", "file", "filter", "flow", "form", "frame", "function",
            "graph", "grid", "group", "guard", "hash", "host", "index", "input",
            "interface", "kernel", "key", "language", "layer", "learn", "link",
            "list", "load", "logic", "loop", "machine", "memory", "message",
            "model", "module", "network", "node", "object", "operation", "output",
            "package", "page", "parse", "path", "pipeline", "platform", "plugin",
            "pointer", "process", "program", "protocol", "query", "queue", "rank",
            "record", "render", "request", "response", "route", "runtime", "safe",
            "schema", "script", "search", "secure", "server", "service", "session",
            "signal", "socket", "sort", "source", "stack", "state", "storage",
            "stream", "string", "structure", "system", "table", "task", "test",
            "text", "thread", "token", "tool", "trace", "tree", "type", "update",
            "user", "value", "vector", "version", "view", "virtual", "web", "worker",
            "workflow", "word"]

def main():
    destination = Path(sys.argv[1] if len(sys.argv) > 1 else "data/dictionary.txt")
    words = set(SEEDS)
    for prefix in PREFIXES:
        for suffix in SUFFIXES:
            words.add(prefix + suffix)
    # Deterministically fill to exactly 10,000 entries with systematic compounds.
    bases = sorted(words)
    i = 0
    while len(words) < 10000:
        a = bases[i % len(bases)]
        b = bases[(i * 37 + 19) % len(bases)]
        candidate = a + b
        if candidate.isalpha():
            words.add(candidate)
        i += 1
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text("\n".join(sorted(words)[:10000]) + "\n", encoding="utf-8")
    # The sorted truncation can change the count; ensure the final output is exact.
    final = sorted(words)
    if len(final) > 10000:
        # Keep common seed words first, then deterministic generated entries.
        ordered = list(dict.fromkeys(SEEDS + sorted(words - set(SEEDS))))
        final = ordered[:10000]
    destination.write_text("\n".join(final) + "\n", encoding="utf-8")
    assert len(final) == 10000 and len(set(final)) == 10000

if __name__ == "__main__":
    main()
